182|/* Read at least one byte from the IDAT stream */
183|static int get_idat_bytes(spng_ctx *ctx, uint32_t *bytes_read)
184|{
185|    if(ctx == NULL || bytes_read == NULL) return 1;
186|    if(memcmp(ctx->current_chunk.type, type_idat, 4)) return 1;
187|
188|    int ret;
189|    uint32_t len;
190|
191|    while(!ctx->cur_chunk_bytes_left)
192|    {
193|        ret = read_header(ctx);
194|        if(ret) return ret;
195|
196|        if(memcmp(ctx->current_chunk.type, type_idat, 4)) return SPNG_EIDAT_TOO_SHORT;
197|    }
198|
199|    if(ctx->streaming)
200|    {/* TODO: calculate bytes to read for progressive reads */
201|        len = 8192;
202|        if(len > ctx->current_chunk.length) len = ctx->current_chunk.length;
203|    }
204|    else len = ctx->current_chunk.length;
205|
206|    ret = read_chunk_bytes(ctx, len);
207|
208|    *bytes_read = len;
209|
210|    return ret;
211|}
