135|static int buffer_read_fn(spng_ctx *ctx, void *user, void *data, size_t n)
136|{
137|    if(n > ctx->bytes_left) return SPNG_IO_EOF;
138|
139|    ctx->data = ctx->data + ctx->last_read_size;
140|
141|    ctx->last_read_size = n;
142|    ctx->bytes_left -= n;
143|
144|    return 0;
145|}

