317|int check_ihdr(struct spng_ihdr *ihdr, uint32_t max_width, uint32_t max_height)
318|{
319|    if(ihdr->width > png_u32max || ihdr->width > max_width || !ihdr->width) return SPNG_EWIDTH;
320|    if(ihdr->height > png_u32max || ihdr->height > max_height || !ihdr->height) return SPNG_EHEIGHT;
321|
322|    switch(ihdr->color_type)
323|    {
324|        case SPNG_COLOR_TYPE_GRAYSCALE:
325|        {
326|            if( !(ihdr->bit_depth == 1 || ihdr->bit_depth == 2 ||
327|                  ihdr->bit_depth == 4 || ihdr->bit_depth == 8 ||
328|                  ihdr->bit_depth == 16) )
329|                  return SPNG_EBIT_DEPTH;
330|
331|            break;
332|        }
333|        case SPNG_COLOR_TYPE_TRUECOLOR:
334|        {
335|            if( !(ihdr->bit_depth == 8 || ihdr->bit_depth == 16) )
336|                return SPNG_EBIT_DEPTH;
337|
338|            break;
339|        }
340|        case SPNG_COLOR_TYPE_INDEXED:
341|        {
342|            if( !(ihdr->bit_depth == 1 || ihdr->bit_depth == 2 ||
343|                  ihdr->bit_depth == 4 || ihdr->bit_depth == 8) )
344|                return SPNG_EBIT_DEPTH;
345|
346|            break;
347|        }
348|        case SPNG_COLOR_TYPE_GRAYSCALE_ALPHA:
349|        {
350|            if( !(ihdr->bit_depth == 8 || ihdr->bit_depth == 16) )
351|                return SPNG_EBIT_DEPTH;
352|
353|            break;
354|        }
355|        case SPNG_COLOR_TYPE_TRUECOLOR_ALPHA:
356|        {
357|            if( !(ihdr->bit_depth == 8 || ihdr->bit_depth == 16) )
358|                return SPNG_EBIT_DEPTH;
359|
360|            break;
361|        }
362|    default: return SPNG_ECOLOR_TYPE;
363|    }
364|
365|    if(ihdr->compression_method || ihdr->filter_method)
366|        return SPNG_ECOMPRESSION_METHOD;
367|
368|    if( !(ihdr->interlace_method == 0 || ihdr->interlace_method == 1) )
369|        return SPNG_EINTERLACE_METHOD;
370|
371|    return 0;
372|}

