220|int spng_decoded_image_size(spng_ctx *ctx, int fmt, size_t *out)
221|{
222|    if(ctx == NULL || out == NULL) return 1;
223|
224|    if(!ctx->valid_state) return SPNG_EBADSTATE;
225|
226|    int ret = get_ancillary(ctx);
227|    if(ret) return ret;
228|
229|    size_t res;
230|    if(fmt == SPNG_FMT_RGBA8)
231|    {
232|        if(4 > SIZE_MAX / ctx->ihdr.width) return SPNG_EOVERFLOW;
233|        res = 4 * ctx->ihdr.width;
234|
235|        if(res > SIZE_MAX / ctx->ihdr.height) return SPNG_EOVERFLOW;
236|        res = res * ctx->ihdr.height;
237|    }
238|    else if(fmt == SPNG_FMT_RGBA16)
239|    {
240|        if(8 > SIZE_MAX / ctx->ihdr.width) return SPNG_EOVERFLOW;
241|        res = 8 * ctx->ihdr.width;
242|
243|        if(res > SIZE_MAX / ctx->ihdr.height) return SPNG_EOVERFLOW;
244|        res = res * ctx->ihdr.height;
245|    }
