253|int calculate_subimages(struct spng_subimage sub[7], size_t *widest_scanline, struct spng_ihdr *ihdr, unsigned channels)
254|{
255|    if(sub == NULL || ihdr == NULL) return 1;
256|
257|    if(ihdr->interlace_method == 1)
258|    {
259|        sub[0].width = (ihdr->width + 7) >> 3;
260|        sub[0].height = (ihdr->height + 7) >> 3;
261|        sub[1].width = (ihdr->width + 3) >> 3;
262|        sub[1].height = (ihdr->height + 7) >> 3;
263|        sub[2].width = (ihdr->width + 3) >> 2;
264|        sub[2].height = (ihdr->height + 3) >> 3;
265|        sub[3].width = (ihdr->width + 1) >> 2;
266|        sub[3].height = (ihdr->height + 3) >> 2;
267|        sub[4].width = (ihdr->width + 1) >> 1;
268|        sub[4].height = (ihdr->height + 1) >> 2;
269|        sub[5].width = ihdr->width >> 1;
270|        sub[5].height = (ihdr->height + 1) >> 1;
271|        sub[6].width = ihdr->width;
272|        sub[6].height = ihdr->height >> 1;
273|    }
274|    else
275|    {
276|        sub[0].width = ihdr->width;
277|        sub[0].height = ihdr->height;
278|    }
279|
280|    size_t scanline_width, widest = 0;
281|
282|    int i;
283|    for(i=0; i < 7; i++)
284|    {/* Calculate scanline width in bits, round up to the nearest byte */
285|        if(sub[i].width == 0 || sub[i].height == 0) continue;
286|
287|        scanline_width = channels * ihdr->bit_depth;
288|
289|        if(scanline_width > SIZE_MAX / ihdr->width) return SPNG_EOVERFLOW;
290|        scanline_width = scanline_width * sub[i].width;
291|
292|        scanline_width += 8; /* Filter byte */
293|
294|        if(scanline_width < 8) return SPNG_EOVERFLOW;
295|
296|        /* Round up */
297|        if(scanline_width % 8 != 0)
298|        {
299|            scanline_width = scanline_width + 8;
300|            if(scanline_width < 8) return SPNG_EOVERFLOW;
301|
302|            scanline_width -= (scanline_width % 8);
303|        }
304|
305|        scanline_width /= 8;
306|
307|        sub[i].scanline_width = scanline_width;
308|
309|        if(widest < scanline_width) widest = scanline_width;
310|    }
311|
312|    *widest_scanline = widest;
313|
314|    return 0;
315|}
