374|int check_sbit(struct spng_sbit *sbit, struct spng_ihdr *ihdr)
375|{
376|    if(sbit == NULL || ihdr == NULL) return 1;
377|
378|    if(ihdr->color_type == 0)
379|    {
380|        if(sbit->grayscale_bits == 0) return SPNG_ESBIT;
381|        if(sbit->grayscale_bits > ihdr->bit_depth) return SPNG_ESBIT;
382|    }
383|    else if(ihdr->color_type == 2 || ihdr->color_type == 3)
384|    {
385|        if(sbit->red_bits == 0) return SPNG_ESBIT;
386|        if(sbit->green_bits == 0) return SPNG_ESBIT;
387|        if(sbit->blue_bits == 0) return SPNG_ESBIT;
388|
389|        uint8_t bit_depth;
390|        if(ihdr->color_type == 3) bit_depth = 8;
391|        else bit_depth = ihdr->bit_depth;
392|
393|        if(sbit->red_bits > bit_depth) return SPNG_ESBIT;
394|        if(sbit->green_bits > bit_depth) return SPNG_ESBIT;
395|        if(sbit->blue_bits > bit_depth) return SPNG_ESBIT;
396|    }
397|    else if(ihdr->color_type == 4)
398|    {
399|        if(sbit->grayscale_bits == 0) return SPNG_ESBIT;
400|        if(sbit->grayscale_bits > ihdr->bit_depth) return SPNG_ESBIT;
401|    }
402|    else if(ihdr->color_type == 6)
403|    {
404|        if(sbit->red_bits == 0) return SPNG_ESBIT;
405|        if(sbit->green_bits == 0) return SPNG_ESBIT;
406|        if(sbit->blue_bits == 0) return SPNG_ESBIT;
407|        if(sbit->alpha_bits == 0) return SPNG_ESBIT;
408|
409|        if(sbit->red_bits > ihdr->bit_depth) return SPNG_ESBIT;
