484|/* Validate PNG keyword *str, *str must be 80 bytes */
485|int check_png_keyword(const char str[80])
486|{
487|    if(str == NULL) return 1;
488|    char *end = memchr(str, '\0', 80);
489|
490|    if(end == NULL) return 1; /* unterminated string */
491|    if(end == str) return 1; /* zero-length string */
492|    if(str[0] == ' ') return 1; /* leading space */
493|    if(end[-1] == ' ') return 1; /* trailing space */
494|    if(strstr(str, "  ") != NULL) return 1; /* consecutive spaces */
495|
496|    uint8_t c;
497|    while(str != end)
498|    {
499|        memcpy(&c, str, 1);
500|
501|        if( (c >= 32 && c <= 126) || (c >= 161 && c <= 255) ) str++;
502|        else return 1; /* invalid character */
503|    }
504|
505|    return 0;
506|}
507|
508|/* Validate PNG text *str up to 'len' bytes */
509|int check_png_text(const char *str, size_t len)
510|{/* XXX: are consecutive newlines permitted? */
511|    if(str == NULL || len == 0) return 1;
512|
513|    uint8_t c;
514|    size_t i = 0;
515|    while(i < len)
516|    {
517|        memcpy(&c, str + i, 1);
518|
519|        if( (c >= 32 && c <= 126) || (c >= 161 && c <= 255) || c == 10) i++;
520|        else return 1; /* invalid character */
521|    }
522|
523|    return 0;
524|}
